import sys, re, xml.etree.ElementTree as ET
import numpy as np
ns={'c':'http://www.collada.org/2005/11/COLLADASchema'}
t=ET.parse(sys.argv[1]); r=t.getroot()
up=r.find('.//c:asset/c:up_axis',ns); print('up',up.text if up is not None else None)
geoms={}
for g in r.findall('.//c:library_geometries/c:geometry',ns):
    m=g.find('c:mesh',ns)
    pos=None
    v=m.find('c:vertices',ns)
    src=v.find('c:input[@semantic="POSITION"]',ns).get('source')[1:]
    s=m.find(f'c:source[@id="{src}"]',ns)
    a=np.array(s.find('c:float_array',ns).text.split(),float).reshape(-1,3)
    geoms[g.get('id')]=a
def walk(n,M,d=0):
    for ch in n.findall('c:node',ns):
        m=M.copy()
        for e in ch:
            tag=e.tag.split('}')[1]
            if tag=='matrix': m=m@np.array(e.text.split(),float).reshape(4,4)
            elif tag=='translate': T=np.eye(4);T[:3,3]=list(map(float,e.text.split()));m=m@T
            elif tag in('rotate','scale'): print('  '*d,'!!',tag,e.text)
        info=''
        for ig in ch.findall('c:instance_geometry',ns):
            a=geoms[ig.get('url')[1:]]
            w=(np.c_[a,np.ones(len(a))]@m.T)[:,:3]
            info+=f' min{w.min(0).round(3)} max{w.max(0).round(3)} n={len(a)}'
        print('  '*d,ch.get('name'),info)
        walk(ch,m,d+1)
for vs in r.findall('.//c:visual_scene',ns): walk(vs,np.eye(4))
EOF
python3 -I /tmp/scr/dae.py coronatrix_coll.dae; python3 -I /tmp/scr/dae.py coronatrix_hi.dae 2>&1 | grep -i "tag\|up\|landing"

